/**
 * One swing, every outcome: the data behind the looping picture on the insights page.
 *
 * Generated from the models that are live in Looper (lie penalty, slope of the lie,
 * GSPro carry, altitude, elevation, green release, fairway roll). Do not edit by hand.
 *
 * The swing: a stock 8 iron, 108 mph, 19.5 deg launch, 7300 rpm, which finishes 150 yd
 * from a level fairway lie onto a Bermuda medium green at sea level.
 *
 * Each level adds one layer to the one before. A side slope does not change how far
 * the ball goes, only where it starts, so sideways is worked out on the page:
 * total x sin(side slope x share for that lie).
 */
export const STACK_PIN_YDS = 150
export const STACK_SWING = { ballSpeedMph: 108, launchDeg: 19.5, spinRpm: 7300 } as const
/** Choices per layer, in the order the totals are nested: green setting, lie, up or down slope, elevation, altitude. */
export const STACK_TOTAL_SIZES = [9, 4, 5, 3, 3] as const
/** Lies in the order the data uses them. */
export const STACK_LIES = ['Fairway', 'Rough', 'Deep rough', 'Sand'] as const
/** Side slopes of the lie, in degrees (+ is ball below the feet on the right: it starts right). */
export const STACK_SIDE_SLOPES_DEG = [0, -6, -4, -2, 2, 4, 6] as const
/** How much of a side slope becomes start line, per lie (it depends on the launch angle after the lie). */
export const STACK_SIDE_SHARE = [0.687, 0.687, 0.697, 0.687] as const
const unpack = (packed: string): number[] => packed.split(',').map((value) => Number(value) / 2)
/** Total distance in yards at each level; level n nests inside level n-1 by STACK_TOTAL_SIZES. */
